        (s.players[&b].health
            - (100.
                + (s.regeneration_rates(b).unwrap().health_per_second
                    + s.garen_passive_per_second(b))
                    * (if s.tick == 5400 { 2. } else { 1. })
                    / 30.))
            .abs()
            < 0.001
    );
